user_prompt:
method compare(game: seq<int>, guess: seq<int>) returns (result: seq<int>)
    requires |game| == |guess|    // Both input sequences must have the same length
    requires |game| > 0           // The sequences must not be empty
    ensures |result| == |game|     // The result array has the same length as the input arrays
    ensures forall i :: 0 <= i < |result| ==> result[i] == abs(game[i] - guess[i]) // Each element in result is the absolute difference
{
    var n := |game|;
    var res := new int[n];

    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant forall j :: 0 <= j < i ==> res[j] == abs(game[j] - guess[j]) // All previous results are calculated correctly
    {
        res[i] := abs(game[i] - guess[i]);
        i := i + 1;
    }

    return res;
}
